INSERT INTO _q26_nodes (code, level, parent, name_ar, sort_order, page) VALUES
  ('1', 1, NULL, 'الحوكمة والقيادة المدرسية', 1, NULL),
  ('1.1', 2, '1', 'الرؤية والرسالة والقيم', 1, NULL),
  ('1.1.1', 3, '1.1', 'وضوح رؤية ورسالة المدرسة وقيمها وأهدافها، وانعكاسها على مختلف جوانب العمل المدرسي.', 1, 35),
  ('1.1.1.1', 4, '1.1.1', 'وضوح رؤية ورسالة وقيم المدرسة، ووعي الأطراف المعنية بها وفهمهم لأدوارهم في تحقيقها.', 1, 35),
  ('1.1.1.2', 4, '1.1.1', 'أهداف المدرسة واضحة ومحددة وتتوافق مع الرؤية والرسالة والقيم وتسهم في تحقيقها.', 2, 35),
  ('1.1.1.3', 4, '1.1.1', 'توافق رؤية ورسالة وقيم المدرسة وأهدافها مع توجهات الدولة وسياساتها التعليمية.', 3, 35),
  ('1.1.1.4', 4, '1.1.1', 'توافق قرارات المدرسة وسياساتها وخططها مع الرؤية والرسالة والقيم.', 4, 35),
  ('1.1.1.5', 4, '1.1.1', 'انعكاس الرؤية والرسالة والقيم والأهداف على جوانب العمل المختلفة في المدرسة.', 5, 35),
  ('1.1.2', 3, '1.1', 'واقعية رؤية ورسالة المدرسة وأهدافها التربوية.', 2, 36),
  ('1.1.2.1', 4, '1.1.2', 'توافق رؤية ورسالة المدرسة مع مواردها المادية، من خلال توفير المبنى والمرافق والتجهيزات التي تدعم تحقيق الرؤية والرسالة.', 1, 36),
  ('1.1.2.2', 4, '1.1.2', 'توافق رؤية ورسالة المدرسة مع مواردها البشرية من خلال تعيين موظفين مؤهلين لدعم تحقيق الرؤية والرسالة.', 2, 36),
  ('1.1.2.3', 4, '1.1.2', 'الوضع المالي للمدرسة مستقر، وتوضع تقديرات مستقبلية للموارد المالية، ويتم تطوير استراتيجيات لضمان استدامة الميزانية وتفادي حدوث عجز مالي.', 3, 36),
  ('1.1.3', 3, '1.1', 'مراجعة الرؤية، والرسالة، والأهداف.', 3, 36),
  ('1.1.3.1', 4, '1.1.3', 'تطبيق آلية وإجراءات واضحة ومحددة لمراجعة ومتابعة مدى تحقيق الرؤية والرسالة والأهداف، وبما يتوافق مع توجهات الدولة واحتياجات المدرسة، والتحديث عليها عند الحاجة.', 1, 36),
  ('1.1.3.2', 4, '1.1.3', 'الاستفادة من عملية المراجعة والتحديث في عمليات اتخاذ القرار للمساهمة في تحقيق الرؤية والرسالة.', 2, 37),
  ('1.1.3.3', 4, '1.1.3', 'دور ومشاركة الأطراف المعنية في عمليات مراجعة وتحديث الرؤية والرسالة.', 3, 37),
  ('1.2', 2, '1', 'التخطيط والتنظيم الإداري', 2, NULL),
  ('1.2.1', 3, '1.2', 'الالتزام بالقوانين والأنظمة واللوائح الصادرة عن وزارة التربية والتعليم والتعليم العالي، والجهات الحكومية ذات العلاقة.', 1, 38),
  ('1.2.1.1', 4, '1.2.1', 'التزام المدرسة بتطبيق القوانين والأنظمة واللوائح الصادرة عن وزارة التربية والتعليم والتعليم العالي.', 1, 38),
  ('1.2.1.2', 4, '1.2.1', 'التزام المدرسة بتطبيق القوانين والأنظمة واللوائح الصادرة عن الجهات الحكومية ذات العلاقة.', 2, 38),
  ('1.2.2', 3, '1.2', 'إعداد وتطبيق خطط شاملة تسهم في تحقيق رؤية ورسالة وأهداف المدرسة.', 2, 39),
  ('1.2.2.1', 4, '1.2.2', 'إعداد خطط استراتيجية وسنوية تسهم في تحقيق رؤية ورسالة وأهداف المدرسة.', 1, 39),
  ('1.2.2.2', 4, '1.2.2', 'شمولية وجودة الخطط المدرسية وتلبيتها لاحتياجات المدرسة المختلفة.', 2, 39),
  ('1.2.2.3', 4, '1.2.2', 'تنفيذ الخطط المدرسية وأثرها في تحقيق رؤية ورسالة وأهداف المدرسة وتطوير جودة العمل.', 3, 39),
  ('1.2.2.4', 4, '1.2.2', 'إعداد وتنفيذ خطة متكاملة لإدارة الأزمات والطوارئ تضمن استمرارية العملية التعليمية.', 4, 39),
  ('1.2.3', 3, '1.2', 'إعداد وتطبيق سياسات شاملة ومنظمة للعمل في المدرسة.', 3, 40),
  ('1.2.3.1', 4, '1.2.3', 'إعداد سياسات شاملة وواضحة ومنظمة لكافة جوانب العمل في المدرسة.', 1, 40),
  ('1.2.3.2', 4, '1.2.3', 'نشر السياسات وتعريف كافة الأطراف المعنية بها.', 2, 40),
  ('1.2.3.3', 4, '1.2.3', 'تطبيق السياسات، ودورها في تنظيم العمل المدرسي.', 3, 40),
  ('1.2.3.4', 4, '1.2.3', 'مراجعة وتحديث السياسات بشكلٍ دوري، أو متى تطلبت الحاجة.', 4, 40),
  ('1.2.4', 3, '1.2', 'شمولية الهيكل التنظيمي بما يضمن تحديد الأدوار والمسؤوليات، ويعزز التنسيق والتكامل.', 4, 41),
  ('1.2.4.1', 4, '1.2.4', 'الهيكل التنظيمي شامل، وواضح، ومتوافق مع حجم المدرسة وطبيعتها، لضمان فعالية تنظيم العمل.', 1, 41),
  ('1.2.4.2', 4, '1.2.4', 'يتضمن الهيكل التنظيمي توزيعاً دقيقاً للأدوار والمسؤوليات، ويوضح التسلسل الوظيفي، مما يعزز التنسيق والتكامل بين المهام ويسهل المتابعة.', 2, 41),
  ('1.2.4.3', 4, '1.2.4', 'إعداد توصيف وظيفي دقيق والتعريف به للموظفين، لتحديد مهامهم ومسؤولياتهم.', 3, 41),
  ('1.2.4.4', 4, '1.2.4', 'توزيع وتقسيم المهام بشكلٍ عادل بين الموظفين، وحسب المؤهلات، والإمكانيات، والخبرات.', 4, 42),
  ('1.2.4.5', 4, '1.2.4', 'تطبيق آلية فعالة لتفويض المهام مما يسهم في تحسين العمل وسرعة الإنجاز.', 5, 42),
  ('1.2.4.6', 4, '1.2.4', 'تنفيذ آلية وإجراءات لمتابعة وتغطية غياب الموظفين وضمان التزامهم بمواعيد العمل، مما يضمن استمرارية سير العملية التعليمية وكفاءة الأداء الإداري والتعليمي.', 6, 42),
  ('1.3', 2, '1', 'عمليات المتابعة والمحاسبية', 3, NULL),
  ('1.3.1', 3, '1.3', 'تقييم ومتابعة أداء الموظفين بشكلٍ يسهم في تحسين أدائهم.', 1, 44),
  ('1.3.1.1', 4, '1.3.1', 'تطبيق إجراءات واضحة ومعلنة وذات جودة لمتابعة وتقييم قيادتي المدرسة العليا والوسطى والموظفين، كلٌ حسب وصفه الوظيفي.', 1, 44),
  ('1.3.1.2', 4, '1.3.1', 'تقديم التغذية الراجعة البناءة للموظفين بما يسهم في تطور أدائهم.', 2, 44),
  ('1.3.2', 3, '1.3', 'مراقبة ومتابعة أداء الطلبة بشكلٍ يسهم في دعم تعلمهم وسلوكهم.', 2, 44),
  ('1.3.2.1', 4, '1.3.2', 'تطبيق آلية وإجراءات واضحة وفعالة لمراقبة ومتابعة التحصيل الأكاديمي للطلبة، والاستفادة من تحليل النتائج والمتابعة في اتخاذ القرارات المناسبة لدعم العملية التعليمية.', 1, 44),
  ('1.3.2.2', 4, '1.3.2', 'تطبيق آلية وإجراءات لمراقبة ومتابعة سلوك الطلبة، والاستفادة منها في وضع البرامج والخطط التي تسهم في ضبط وتعزيز سلوكهم.', 2, 45),
  ('1.3.3', 3, '1.3', 'متابعة وتقييم الخطط والبرامج والمشاريع من خلال مؤشرات محددة لتقييم أثرها ومدى فاعليتها.', 3, 45),
  ('1.3.3.1', 4, '1.3.3', 'تطبيق آلية وإجراءات واضحة ومحددة لمتابعة وتقييم الخطط والبرامج والمشاريع، وتحديد مدى فاعليتها في تحقيق الأهداف المحددة.', 1, 45),
  ('1.3.3.2', 4, '1.3.3', 'تحديث الخطط والبرامج بناءً على نتائج التقييم والتغذية الراجعة (عند الحاجة).', 2, 45),
  ('1.3.4', 3, '1.3', 'تطبيق أنظمة أتمتة لإدارة العمليات التعليمية والإدارية، بما يعزز كفاءة الأداء وفاعلية المتابعة والمساءلة.', 4, 46),
  ('1.3.4.1', 4, '1.3.4', 'تفعيل أنظمة أتمتة معتمدة لإدارة العمليات التعليمية والإدارية.', 1, 46),
  ('1.3.4.2', 4, '1.3.4', 'الاستخدام المنهجي لأنظمة الأتمتة في متابعة أداء الموظفين، والطلبة، وتنفيذ الخطط المدرسية.', 2, 46),
  ('1.3.4.3', 4, '1.3.4', 'انتظام ودقة إدخال البيانات وتحديثها، بما يضمن موثوقية التقارير والمخرجات الصادرة عن أنظمة الأتمتة.', 3, 46),
  ('1.3.5', 3, '1.3', 'دور المالك/ مجلس الإدارة في المتابعة واتخاذ القرارات الاستراتيجية، وتقديم الدعم لتحقيق أهداف المدرسة.', 5, 47),
  ('1.3.5.1', 4, '1.3.5', 'متابعة المالك / مجلس الإدارة لتقدم المدرسة نحو تحقيق أهدافها الاستراتيجية.', 1, 47),
  ('1.3.5.2', 4, '1.3.5', 'دعم المالك / مجلس الإدارة للمدرسة في تنفيذ الخطة الاستراتيجية وتقديم التوجيه اللازم لتحقيق أهدافها.', 2, 47),
  ('1.4', 2, '1', 'الدراسة الذاتية والتخطيط للتحسين', 4, NULL),
  ('1.4.1', 3, '1.4', 'جودة إعداد الدراسة الذاتية وواقعيتها.', 1, 49),
  ('1.4.1.1', 4, '1.4.1', 'جودة آلية وإجراءات تقييم المدرسة لأدائها وإعداد تقرير الدراسة الذاتية.', 1, 49),
  ('1.4.1.2', 4, '1.4.1', 'مشاركة كافة الأطراف المعنية في عملية إعداد الدراسة الذاتية، وتحديد جوانب القوة والجوانب التي تحتاج إلى تحسين.', 2, 49),
  ('1.4.1.3', 4, '1.4.1', 'دقة البيانات وواقعية تقرير الدراسة الذاتية في التعبير عن الواقع الفعلي للمدرسة.', 3, 49),
  ('1.4.1.4', 4, '1.4.1', 'توفير الأدلة الداعمة التي تتسق مع نتائج تقرير الدراسة الذاتية.', 4, 49),
  ('1.4.1.5', 4, '1.4.1', 'توافق نتائج الدراسة الذاتية مع نتائج التقييم الخارجي لفريق الاعتماد.', 5, 49),
  ('1.4.2', 3, '1.4', 'جودة خطة التحسين ومدى توافقها مع نتائج عملية الدراسة الذاتية للمدرسة.', 2, 49),
  ('1.4.2.1', 4, '1.4.2', 'شمولية خطة التحسين لكافة جوانب التحسين التي حددتها المدرسة لنفسها في تقرير الدراسة الذاتية.', 1, 49),
  ('1.4.2.2', 4, '1.4.2', 'جودة الخطة وملائمتها لإمكانات المدرسة ومواردها المادية والبشرية.', 2, 49),
  ('1.4.3', 3, '1.4', 'تقرير تقدم الأداء شامل ويعكس مدى تقدم أداء المدرسة.', 3, 50),
  ('1.4.3.1', 4, '1.4.3', 'يعكس تقرير تقدم الأداء الإجراءات التي قامت بها المدرسة لتعزيز جوانب التحسين.', 1, 50),
  ('1.4.3.2', 4, '1.4.3', 'يوفر التقرير أدلة داعمة توضح تحقيق تحسن وتقدم في الأداء.', 2, 50),
  ('1.5', 2, '1', 'التواصل والشراكة', 5, NULL),
  ('1.5.1', 3, '1.5', 'التواصل مع الموظفين وضمان رضاهم واستقرارهم الوظيفي.', 1, 52),
  ('1.5.1.1', 4, '1.5.1', 'جودة آلية وطرق التواصل بين القيادة والموظفين، وبين الموظفين وبعضهم البعض، بما يضمن سهولة وسرعة إنجاز العمل.', 1, 52),
  ('1.5.1.2', 4, '1.5.1', 'الجو العام في المدرسة إيجابي، ويتسم بالتعاون والانتماء والإحساس بالمسؤولية، ويحقق الاستقرار الوظيفي.', 2, 52),
  ('1.5.1.3', 4, '1.5.1', 'صرف رواتب الموظفين في الوقت المحدد ودون تأخير، لضمان استقرار الوضع المالي للموظفين بما ينعكس على استقرارهم الوظيفي.', 3, 52),
  ('1.5.1.4', 4, '1.5.1', 'تطبيق نظام حوافز يُعزز استقرار الموظفين ويحفزهم على تقديم أداء متميز، بناءً على الإنجازات والأهداف المحققة.', 4, 52),
  ('1.5.1.5', 4, '1.5.1', 'تطبيق آلية وإجراءات منتظمة لقياس رضا الموظفين وجمع مقترحاتهم باستخدام أدوات متنوعة، والاستفادة منها في اتخاذ قرارات التحسين والتطوير.', 5, 52),
  ('1.5.2', 3, '1.5', 'التواصل مع الطلبة وضمان مشاركتهم والاستفادة من آرائهم في صنع القرار.', 2, 52),
  ('1.5.2.1', 4, '1.5.2', 'آلية وطرق التواصل مع الطلبة متنوعة ومنتظمة، لضمان الوعي الكامل بالخدمات المقدمة والمشاركة الفعالة في الحياة المدرسية.', 1, 52),
  ('1.5.2.2', 4, '1.5.2', 'آلية وإجراءات قياس رضا الطلبة وأخذ مقترحاتهم متنوعة ومنتظمة وتتناسب مع الفئات العمرية المختلفة، ويتم الاستفادة منها في إجراء التعديلات وإيجاد الحلول لضمان جودة الخدمات المقدمة في المدرسة.', 2, 52),
  ('1.5.2.3', 4, '1.5.2', 'فعالية دور المجلس الطلابي في الحياة المدرسية وتوصيل صوت الطلبة.', 3, 53),
  ('1.5.3', 3, '1.5', 'التواصل مع أولياء الأمور ومشاركتهم في الحياة المدرسية.', 3, 53),
  ('1.5.3.1', 4, '1.5.3', 'آلية وطرق التواصل مع أولياء الأمور متنوعة وفعالة ومنتظمة.', 1, 53),
  ('1.5.3.2', 4, '1.5.3', 'تنفيذ أنشطة وبرامج لجذب وتعزيز مشاركة أولياء الأمور في الحياة المدرسية.', 2, 53),
  ('1.5.3.3', 4, '1.5.3', 'إشراك أولياء الأمور في العملية التعليمية، ودمجهم في دعم تعلم أبنائهم، وتعزيز أدائهم الأكاديمي والشخصي والاجتماعي.', 3, 53),
  ('1.5.3.4', 4, '1.5.3', 'تطبيق نظام للاستجابة لشكاوى أولياء الأمور والعمل على حلها بسرعة وفعالية.', 4, 53),
  ('1.5.3.5', 4, '1.5.3', 'قياس رضا أولياء الأمور عن جودة التعليم وكافة الخدمات المدرسية.', 5, 53),
  ('1.5.4', 3, '1.5', 'التواصل مع المجتمع الخارجي مما يعزز دور المدرسة في المجتمع ويدعم تعلم الطلبة.', 4, 54),
  ('1.5.4.1', 4, '1.5.4', 'آلية وطرق تواصل المدرسة مع المجتمع الخارجي (المحلي والدولي) متنوعة ومنتظمة، مما يعزز دور المدرسة في المجتمع ويدعم تعلم الطلبة.', 1, 54),
  ('1.5.4.2', 4, '1.5.4', 'الاستفادة من مؤسسات المجتمع في دعم تعلم الطلبة واحتياجاتهم المختلفة.', 2, 54),
  ('2', 1, NULL, 'الأداء التعليمي وبيئة التعلم', 2, NULL),
  ('2.1', 2, '2', 'المناهج الدراسية', 1, NULL),
  ('2.1.1', 3, '2.1', 'شمولية المنهج الدراسي، وتوافقه مع رؤية ورسالة المدرسة.', 1, 83),
  ('2.1.1.1', 4, '2.1.1', 'يتوافق المنهج الدراسي مع رؤية ورسالة المدرسة وأهدافها.', 1, 83),
  ('2.1.1.2', 4, '2.1.1', 'يعزز المنهج الدراسي الكفاءات المحلية والعالمية مع مراعاة السياقات الثقافية المحلية.', 2, 83),
  ('2.1.1.3', 4, '2.1.1', 'ملاءمة المصادر التعليمية للمنهج المعتمد في المدرسة ودعمها لتحقيق أهدافه.', 3, 83),
  ('2.1.1.4', 4, '2.1.1', 'تتوافق المعايير المطبقة مع التوقعات التعليمية للمرحلة الدراسية.', 4, 83),
  ('2.1.1.5', 4, '2.1.1', 'يشمل المنهج الدراسي مجالات تعليمية متنوعة تسهم في تنمية متكاملة للطلبة.', 5, 83),
  ('2.1.1.6', 4, '2.1.1', 'يحقق المنهج توازناً بين الجوانب المعرفية والمهارية والقيمية ويراعي احتياجات الطلبة.', 6, 83),
  ('2.1.2', 3, '2.1', 'التخطيط لتطبيق المنهج الدراسي والالتزام بتنفيذ الخطط بكفاءة.', 2, 84),
  ('2.1.2.1', 4, '2.1.2', 'إعداد خطط ذات جودة (سنوية/ فصلية) شاملة وواضحة لتطبيق المنهج لكل مرحلة دراسية، وفقاً لمتطلبات المنهج واحتياجات الطلبة.', 1, 84),
  ('2.1.2.2', 4, '2.1.2', 'مراعاة تكامل المواد الدراسية المختلفة عند التخطيط للمنهج.', 2, 84),
